   455	    /**
   456	     * HTML에서 배송 상태를 파싱합니다.
   457	     *
   458	     * @param html 파싱할 HTML 문자열
   459	     * @param trackingNumber 로깅용 운송장 번호
   460	     * @return 배송 상태 문자열
   461	     * @throws ShipmentException 파싱 실패 시 발생
   462	     */
   463	    private String parseStatusFromHtml(String html, String trackingNumber) {
   464	        try {
   465	            Document doc = Jsoup.parse(html);
   466	            Elements rows = doc.select(STATUS_SELECTOR);
   467	
   468	            if (rows.isEmpty()) {
   469	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
   470	                throw new ShipmentException(
   471	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   472	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
   473	                );
   474	            }
   475	
   476	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
   477	            String statusText = rows.last().select("td").get(4).text().trim();
   478	
   479	            if (statusText.isEmpty()) {
   480	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
   481	                throw new ShipmentException(
   482	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   483	                        "배송 상태 정보를 찾을 수 없습니다."
   484	                );
   485	            }
   486	
   487	            return statusText;
   488	
   489	        } catch (IndexOutOfBoundsException e) {
   490	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   491	            throw new ShipmentException(
   492	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   493	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
   494	                    e
   495	            );
   496	        } catch (Exception e) {
   497	            if (e instanceof ShipmentException) {
   498	                throw (ShipmentException) e;
   499	            }
   500	
   501	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   502	            throw new ShipmentException(
   503	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   504	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
   505	                    e
   506	            );
   507	        }
   508	    }
