        // 4. Order 생성
        Order order = orderCommandService.createInstantOrder(
                buyer,
                saleBid,
                addressId,
                isWarehouseStorage,
                paymentRequest
        );

        // 5. OrderBid 생성 및 저장
        OrderBid orderBid = createInstantOrderBid(order, saleBid, sale);

        return orderBid;
    } catch (Exception e) {
